  globals.window["NINTENDO64_AUDIO_BUFFER_SIZE"] = 1024
  globals.window["NINTENDO64_GAME_RUNNING"] = true
  globals.window["NINTENDO64_SOUND_ENABLED"] = true
  globals.window["NINTENDO64_CONTAINER"] = null
  globals.window["NINTENDO64_ROM_NAME"] = "NO NAME"
  globals.window["NINTENDO64_PAUSED_FRAME_ANIMATION"] = null
